"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["61785"],{76486(e){e.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.inscricao.conta_id_obrigatorio","status":403,"titulo":"O token precisa trazer o claim sub"},"descricao":{"codigo":"uniplus.selecao.inscricao.conta_id_obrigatorio","requisitos":[],"oQueAconteceu":["A inscri\xe7\xe3o pertence \xe0 conta de quem a faz, e \xe9 esse identificador (`contaId`\\nno contrato; no token de acesso, a informa\xe7\xe3o chamada `sub`) que liga a\\ninscri\xe7\xe3o ao seu dono e confere, depois, que s\xf3 ele a consulta ou altera. O\\ntoken de quem pediu chegou sem esse identificador, e a API recusa com **403**\\nem vez de criar uma inscri\xe7\xe3o sem dono ou de abrir a de outra pessoa. A\\nopera\xe7\xe3o recusada n\xe3o criou nem alterou nada: uma inscri\xe7\xe3o que j\xe1 existia\\ncontinua como estava.","A mensagem de detalhe da resposta de erro (o campo `detail`) diz qual opera\xe7\xe3o\\nfoi recusada: iniciar a inscri\xe7\xe3o, acess\xe1-la ou listar as inscri\xe7\xf5es da\\npr\xf3pria pessoa."],"comoResolver":["Encerre a sess\xe3o, entre de novo no Uni+ e repita a opera\xe7\xe3o; a nova entrada\\npode trazer o token com o identificador. Se o erro persistir, o problema est\xe1\\nna conta ou na integra\xe7\xe3o com o provedor de identidade: acione o suporte\\nt\xe9cnico do Uni+, que precisa investigar a causa antes que a inscri\xe7\xe3o seja\\nposs\xedvel."],"ondeAparece":["In\xedcio da inscri\xe7\xe3o","Consulta e demais opera\xe7\xf5es do candidato sobre a pr\xf3pria inscri\xe7\xe3o","Lista das inscri\xe7\xf5es do pr\xf3prio candidato"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Inscricao"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"3eb7bd1a0a2ae187ab8630a6fec1e327066b7a40"}}')}}]);